-- 23-treatment-association.sql
-- V5-SPACETENANCYKEY-001, multi-space step 2.3 (plan V204 §3 row 2.3, §3.0). File 23 of 25.
-- Validates treatment_association_workspace_id_fkey, which v5-tenancykey-001 file 23 (23-fk-treatment-association.sql) added NOT VALID, after the
--   all-row sweep. Stamp 5.3.14-tenancyvalidate-001-treatment-association.
-- GENERATED by generate.mjs (table list, order and env fingerprints: v5-tenancykey-001/owner-classes.json). Edit
--   the generator, run `node generate.mjs --write`; validate.test.js reds on any difference.
--
-- WHAT, in one transaction:
--   0. LOCK treatment_association IN SHARE UPDATE EXCLUSIVE MODE and spaces IN ROW SHARE MODE: the two locks VALIDATE takes,
--      taken first so the sweep runs under them. Reads and writes of both tables go on. A write meanwhile is
--      checked by the key itself (a NOT VALID key checks every new or updated row), so no row naming no Space
--      can arrive between the sweep and VALIDATE.
--   1. The guard ($pregate$, read-only: the runner's --dry-run runs this block alone): the env and the database's
--      fingerprint; v5-tenancykey-001 file 23 applied (stamp 5.3.13-tenancykey-001-fk-treatment-association); the key there in 2.1's shape
--      (workspace_id alone -> public.spaces(id), ON DELETE RESTRICT) and NOT VALID; then THE ALL-ROW SWEEP, every
--      row, no deleted_at filter (Migration Authoring Rule, L-058: VALIDATE trips on a soft-deleted row exactly as
--      on a live one):
--        a. rows whose workspace_id names no row of public.spaces (VALIDATE would raise 23503 on them);
--        b. rows whose workspace_id IS NULL, counted separately: a MATCH SIMPLE key passes a NULL, so VALIDATE
--           alone would not see them, and a validated key must mean every row names a Space.
--      Either count above 0 refuses, naming both counts and up to five of the values, and changes nothing.
--   2. ALTER TABLE public.treatment_association VALIDATE CONSTRAINT treatment_association_workspace_id_fkey (timed: a NOTICE gives the milliseconds), then
--      convalidated read back.
--   3. The key's comment says it is validated; the stamp.
-- ENV. psql -v env=prod|staging (scripts/tenancykey-apply.py --dir v5-tenancyvalidate-001 passes it). Without
--   -v env psql cannot parse the set_config line and nothing runs. Any other value, or a database without that
--   env's schema_version fingerprint, refuses.
-- DEPLOYED CODE (the falsifiable test). VALIDATE changes nothing a write meets: the NOT VALID key has checked every
--   INSERT and UPDATE of this table since file 23 of v5-tenancykey-001. It proves the rows already there.
-- LOCKS. SHARE UPDATE EXCLUSIVE on treatment_association and ROW SHARE on spaces, to COMMIT; two scans of treatment_association (the
--   sweep, then VALIDATE's own). lock_timeout 5s: a wait fails fast (55P03) having changed nothing. The runner
--   refuses at :58-:02 and 07:00-08:00 UTC.
-- RE-RUN. With the stamp present nothing changes. A validated key without the stamp refuses: something other than
--   this file validated it.
-- ROLLBACK: 0r-rollback.sql. A validated key cannot be un-validated in place: the rollback drops it and adds it
--   again NOT VALID, with 2.1's comment.

BEGIN;

SET LOCAL lock_timeout = '5s';
SELECT set_config('tenancyvalidate.env', :'env', true) AS env \gset tv_

LOCK TABLE public.treatment_association IN SHARE UPDATE EXCLUSIVE MODE;
LOCK TABLE public.spaces IN ROW SHARE MODE;

-- ── 1. The guard and the all-row sweep (read-only). ──────────────────────────────────────────────────────
DO $pregate$
DECLARE
  v_env text := current_setting('tenancyvalidate.env', true);
  v_valid boolean;
  v_orphan bigint;
  v_null bigint;
  v_sample text;
BEGIN
  IF v_env IS NULL OR v_env NOT IN ('prod', 'staging') THEN
    RAISE EXCEPTION 'v5-tenancyvalidate-001 23 (treatment_association) refused, nothing changed: env is %, not prod or staging.', coalesce(quote_literal(v_env), 'unset')
      USING HINT = 'Run it with psql -v env=prod or -v env=staging (scripts/tenancykey-apply.py --dir v5-tenancyvalidate-001 does).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.schema_version
                  WHERE version = CASE v_env WHEN 'prod' THEN '4.0.0-pot-001' ELSE '4.23.9-cascadesweep-001-rollback' END)
     OR EXISTS (SELECT 1 FROM public.schema_version
                 WHERE version = CASE v_env WHEN 'prod' THEN '4.23.9-cascadesweep-001-rollback' ELSE '4.0.0-pot-001' END) THEN
    RAISE EXCEPTION 'v5-tenancyvalidate-001 23 (treatment_association) refused, nothing changed: this database does not carry the % fingerprint (v5-tenancykey-001/owner-classes.json "fingerprint").', v_env
      USING HINT = 'The -v env value names the other database. Check which URL this is before anything else.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.schema_version WHERE version = '5.3.14-tenancyvalidate-001-treatment-association') THEN
    RAISE NOTICE 'v5-tenancyvalidate-001 23 (treatment_association): stamp 5.3.14-tenancyvalidate-001-treatment-association present; nothing to check.';
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.schema_version WHERE version = '5.3.13-tenancykey-001-fk-treatment-association') THEN
    RAISE EXCEPTION 'v5-tenancyvalidate-001 23 (treatment_association) refused, nothing changed: v5-tenancykey-001 file 23 has not run (stamp 5.3.13-tenancykey-001-fk-treatment-association absent).'
      USING HINT = 'Step 2.1 adds the key this file validates. Apply it first.';
  END IF;
  SELECT k.convalidated
    FROM pg_constraint k
    JOIN pg_class c ON c.oid = k.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_attribute a ON a.attrelid = k.conrelid AND a.attnum = k.conkey[1]
    JOIN pg_class f ON f.oid = k.confrelid
    JOIN pg_namespace fn ON fn.oid = f.relnamespace
    JOIN pg_attribute fa ON fa.attrelid = k.confrelid AND fa.attnum = k.confkey[1]
   WHERE n.nspname = 'public' AND c.relname = 'treatment_association' AND k.conname = 'treatment_association_workspace_id_fkey' AND k.contype = 'f'
     AND cardinality(k.conkey) = 1 AND a.attname = 'workspace_id'
     AND cardinality(k.confkey) = 1 AND fn.nspname = 'public' AND f.relname = 'spaces' AND fa.attname = 'id'
     AND k.confdeltype = 'r'
    INTO v_valid;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'v5-tenancyvalidate-001 23 (treatment_association) refused, nothing changed: treatment_association_workspace_id_fkey is not on public.treatment_association in the shape v5-tenancykey-001 made (workspace_id alone -> public.spaces(id), ON DELETE RESTRICT).'
      USING HINT = 'Something changed the key since step 2.1. Find what, before anything else.';
  END IF;
  IF v_valid THEN
    RAISE EXCEPTION 'v5-tenancyvalidate-001 23 (treatment_association) refused, nothing changed: treatment_association_workspace_id_fkey is already validated but stamp 5.3.14-tenancyvalidate-001-treatment-association is absent.'
      USING HINT = 'Something other than this file validated it. Find what, before anything else.';
  END IF;

  -- The all-row sweep: every row, soft-deleted ones included.
  SELECT count(*) FILTER (WHERE t.workspace_id IS NOT NULL
                            AND NOT EXISTS (SELECT 1 FROM public.spaces s WHERE s.id = t.workspace_id)),
         count(*) FILTER (WHERE t.workspace_id IS NULL)
    INTO v_orphan, v_null
    FROM public.treatment_association t;
  RAISE NOTICE 'v5-tenancyvalidate-001 23 (treatment_association) sweep, every row (deleted included): % row(s) name no Space, % row(s) NULL.', v_orphan, v_null;
  IF v_orphan > 0 OR v_null > 0 THEN
    SELECT string_agg(format('%s: %s row(s)', coalesce(x.workspace_id::text, 'NULL'), x.n), ', ' ORDER BY x.workspace_id::text)
      INTO v_sample
      FROM (SELECT t.workspace_id, count(*) AS n
              FROM public.treatment_association t
             WHERE t.workspace_id IS NULL
                OR NOT EXISTS (SELECT 1 FROM public.spaces s WHERE s.id = t.workspace_id)
             GROUP BY t.workspace_id
             ORDER BY t.workspace_id::text NULLS FIRST
             LIMIT 5) x;
    RAISE EXCEPTION 'v5-tenancyvalidate-001 23 (treatment_association) refused, nothing changed: the all-row sweep found % row(s) naming no Space and % row(s) with a NULL workspace_id (%).', v_orphan, v_null, v_sample
      USING HINT = 'Triage each row (L-058): a row that names no Space is either repaired to its Space or, if it is test debris, hard-deleted with Dave''s OK. Never filter the sweep.';
  END IF;
END $pregate$;

-- ── 2. VALIDATE, once. ───────────────────────────────────────────────────────────────────────────────────
DO $ddl$
DECLARE
  v_t0 timestamptz;
  v_valid boolean;
BEGIN
  IF EXISTS (SELECT 1 FROM public.schema_version WHERE version = '5.3.14-tenancyvalidate-001-treatment-association') THEN
    RAISE NOTICE 'v5-tenancyvalidate-001 23 (treatment_association): already applied; nothing changed.';
    RETURN;
  END IF;

  v_t0 := clock_timestamp();
  ALTER TABLE public.treatment_association VALIDATE CONSTRAINT treatment_association_workspace_id_fkey;
  RAISE NOTICE 'v5-tenancyvalidate-001 23 (treatment_association): VALIDATE CONSTRAINT treatment_association_workspace_id_fkey took % ms.',
    round((extract(epoch FROM clock_timestamp() - v_t0) * 1000)::numeric, 1);

  SELECT k.convalidated
    FROM pg_constraint k
    JOIN pg_class c ON c.oid = k.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_attribute a ON a.attrelid = k.conrelid AND a.attnum = k.conkey[1]
    JOIN pg_class f ON f.oid = k.confrelid
    JOIN pg_namespace fn ON fn.oid = f.relnamespace
    JOIN pg_attribute fa ON fa.attrelid = k.confrelid AND fa.attnum = k.confkey[1]
   WHERE n.nspname = 'public' AND c.relname = 'treatment_association' AND k.conname = 'treatment_association_workspace_id_fkey' AND k.contype = 'f'
     AND cardinality(k.conkey) = 1 AND a.attname = 'workspace_id'
     AND cardinality(k.confkey) = 1 AND fn.nspname = 'public' AND f.relname = 'spaces' AND fa.attname = 'id'
     AND k.confdeltype = 'r'
    INTO v_valid;
  IF v_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'v5-tenancyvalidate-001 23 (treatment_association): treatment_association_workspace_id_fkey is not validated after VALIDATE; rolled back.';
  END IF;
END $ddl$;

-- ── 3. Comment and the stamp. ────────────────────────────────────────────────────────────────────────────
COMMENT ON CONSTRAINT treatment_association_workspace_id_fkey ON public.treatment_association IS
  'V5-SPACETENANCYKEY-001 (v5-tenancykey-001 23, step 2.1; validated by v5-tenancyvalidate-001 23, step 2.3). A row''s Space is a row of public.spaces. RESTRICT: a Space with rows here cannot be deleted. Validated after an all-row sweep (soft-deleted rows included).';

INSERT INTO public.schema_version (version, description)
VALUES ('5.3.14-tenancyvalidate-001-treatment-association',
        'TENANCYVALIDATE treatment_association: V5-SPACETENANCYKEY-001 (multi-space step 2.3, file 23 of 25). '
        'All-row sweep (no deleted_at filter) found 0 rows naming no Space and 0 NULL, then VALIDATE CONSTRAINT '
        'treatment_association_workspace_id_fkey. Section '
        || current_setting('tenancyvalidate.env') || '.')
ON CONFLICT (version) DO NOTHING;

COMMIT;
